const data = $json.body ?? $json;

const required = ['studentName', 'studentEmail', 'lecturerName', 'topic', 'date', 'startTime', 'endTime'];
const missing = required.filter((key) => !String(data[key] ?? '').trim());

if (missing.length) {
  throw new Error(`Data konsultasi belum lengkap: ${missing.join(', ')}`);
}

const clean = (value, max = 1000) =>
  String(value ?? '').trim().slice(0, max);

const payload = {
  username: 'Konsultasi Peer Polimedia',
  allowed_mentions: { parse: [] },
  embeds: [{
    title: '📚 Pengajuan Jadwal Konsultasi Baru',
    color: 0x259148,
    fields: [
      { name: 'Nama Mahasiswa', value: clean(data.studentName, 150), inline: true },
      { name: 'Email Mahasiswa', value: clean(data.studentEmail, 200), inline: true },
      { name: 'Dosen', value: clean(data.lecturerName, 150), inline: true },
      { name: 'Topik Konsultasi', value: clean(data.topic, 1000), inline: false },
      { name: 'Tanggal', value: clean(data.date, 50), inline: true },
      { name: 'Waktu', value: `${clean(data.startTime, 20)}–${clean(data.endTime, 20)}`, inline: true },
      { name: 'Catatan', value: clean(data.notes || 'Tidak ada catatan', 1000), inline: false }
    ],
    footer: { text: 'Peer Polimedia • Notifikasi konsultasi' },
    timestamp: new Date().toISOString()
  }]
};

return [{ json: { discordPayload: payload } }];
